def is_valid_graph(edges, n=14):
    # Check degrees
    deg = [0]*n
    for u,v in edges:
        deg[u] += 1
        deg[v] += 1
    if min(deg) < 5 or max(deg) > 7:
        return False
    if len(edges) < 21 or len(edges) > 36:
        return False
    return True

def chromatic_number(edges, n=14):
    # Try to find chromatic number using greedy or exact
    # Build adjacency
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Try k-coloring for k=2,3,4,5 using backtracking
    for k in range(2, 6):
        colors = [-1]*n
        # Simple backtracking
        def backtrack(v):
            if v == n:
                return True
            used = set()
            for nb in adj[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            for c in range(k):
                if c not in used:
                    colors[v] = c
                    if backtrack(v+1):
                        return True
                    colors[v] = -1
            return False
        if backtrack(0):
            return k
    return None

