# Let's try a circulant graph approach
# C_14 with chords connecting vertices at distance 2, 3, etc.

def circulant_edges(n, jumps):
    edges = set()
    for i in range(n):
        for j in jumps:
            v = (i + j) % n
            if i < v:
                edges.add((i, v))
    return list(edges)

# Try different circulant graphs
